const notice = $input.first().json;
const facts = notice.snapshot?.state?.facts ?? {};
const clean = (value, fallback = 'Não informado') => {
  if (typeof value !== 'string' && typeof value !== 'number') return fallback;
  return String(value).replace(/\s+/g, ' ').trim().slice(0, 450) || fallback;
};
const fact = key => facts[key]?.value;
const contact = clean(fact('whatsapp'));
const normShort = String(notice.snapshot?.customer_message || '').normalize('NFD').replace(/\p{M}/gu, '').toLowerCase().replace(/\s+/g, ' ').trim();
const isShortAccept = /^(?:sim|ok|confirmo|esta correto|esta tudo certo|tudo certo|pode enviar|pode encaminhar|fechado|beleza|isso mesmo|de acordo)[.!\s]*$/.test(normShort);
const rawMsg = typeof notice.snapshot?.customer_message === 'string' ? notice.snapshot.customer_message.replace(/\s+/g, ' ').trim() : '';
const quoted = rawMsg && !isShortAccept ? rawMsg : '';

const obsParts = ['WhatsApp do cliente: ' + contact];
const atividade = clean(fact('atividade') || fact('segmento'), '');
if (atividade) obsParts.push('Atividade/Segmento: ' + atividade);
const aplicacao = clean(fact('aplicacao'), '');
if (aplicacao) obsParts.push('Aplicação: ' + aplicacao);
const particularidades = clean(fact('particularidades'), '');
if (particularidades) obsParts.push('Particularidades: ' + particularidades);
const rawPend = fact('pendencias');
const pendList = Array.isArray(rawPend) ? rawPend : (rawPend ? [rawPend] : []);
const pendText = pendList.map(p => clean(p, '')).filter(Boolean).join('; ');
if (pendText) obsParts.push('Pendências: ' + pendText);
const atts = Array.isArray(notice.snapshot?.attachments) ? notice.snapshot.attachments : [];
const attNames = atts.map(a => clean(a?.name || a?.filename || a?.type, '')).filter(Boolean).join(', ');
if (attNames) obsParts.push('Anexos: ' + attNames);
if (quoted) obsParts.push('Solicitação: ' + quoted);
const observation = clean(obsParts.join(' | '));

const product = fact('produto') ?? fact('produto_familia');
const spec = fact('especificacao') ?? [fact('dimensoes'), fact('material'), fact('espessura')]
  .filter(value => typeof value === 'string' || typeof value === 'number').join(' | ');
let quantity = fact('quantidade');
if (!quantity && typeof fact('area_m2_validada') === 'number') {
  quantity = String(fact('area_m2_validada')) + ' m²';
}
if (!quantity && typeof fact('dimensoes') === 'string') {
  const m2 = fact('dimensoes').match(/(\d+(?:[.,]\d+)*\s*(?:m²|m2|metros?\s+quadrados?))(?![a-z0-9])/i);
  if (m2) quantity = m2[1];
}
const cidadeSede = clean(fact('cidade_sede'), '');
const ufSede = clean(fact('uf_sede'), '');
const regiao = clean(fact('regiao'), '');
const cityOrRegion = (cidadeSede && ufSede)
  ? (cidadeSede + '/' + ufSede.toUpperCase())
  : (cidadeSede || ufSede || (regiao ? 'Região ' + regiao : ''));

const fields = [
  notice.seller_name, fact('nome'), fact('empresa'), fact('cnpj'), fact('email'),
  product, spec, quantity, cityOrRegion, observation, notice.opportunity_id,
];
return [{ json: {
  recipient: notice.recipient,
  components: { component: [{ bodyParameters: { parameter: fields.map(value => ({ text: clean(value) })) } }] },
} }];

